import type { Finding, LedgerRow, Patch, ResidueEntry, Verdict } from '../contracts/index.js';

/** Append-only ledger writing plus reopen detection by fingerprint. */

export interface LedgerSink {
  readonly append: (row: LedgerRow) => void;
  readonly now: () => string;
}

export interface Reopen {
  readonly fingerprint: string;
  readonly findingIds: readonly string[];
  readonly previousRound: number;
}

export interface RoundLedger {
  readonly finding: (finding: Finding) => void;
  readonly verified: (findingId: string, verdict: Verdict) => void;
  readonly patchApplied: (patch: Patch) => void;
  readonly reopened: (reopen: Reopen) => void;
  readonly residue: (entry: ResidueEntry) => void;
}

/** Every row this round shares one timestamp source and one round number. */
export const roundLedger = (sink: LedgerSink, round: number): RoundLedger => {
  const at = (): { readonly at: string; readonly round: number } => ({ at: sink.now(), round });
  return {
    finding: finding => sink.append({ ...at(), kind: 'finding', finding }),
    verified: (findingId, verdict) => sink.append({ ...at(), kind: 'verified', findingId, verdict }),
    patchApplied: patch => sink.append({ ...at(), kind: 'patch-applied', patch }),
    reopened: reopen => sink.append({ ...at(), kind: 'reopened', ...reopen }),
    residue: entry => sink.append({ ...at(), kind: 'residue', entry }),
  };
};

export type PatchedRounds = Readonly<Record<string, number>>;

const reopenOf = (finding: Finding, patchedAt: PatchedRounds): Reopen | undefined => {
  const previousRound = patchedAt[finding.fingerprint];
  if (previousRound === undefined || previousRound >= finding.round) return undefined;
  return { fingerprint: finding.fingerprint, findingIds: [finding.id], previousRound };
};

/** A fingerprint patched in round N and red again in round N+1 is an oscillation. */
export const detectReopens = (findings: readonly Finding[], patchedAt: PatchedRounds): readonly Reopen[] =>
  findings
    .map(finding => reopenOf(finding, patchedAt))
    .filter((reopen): reopen is Reopen => reopen !== undefined);

export const markPatched = (patchedAt: PatchedRounds, findings: readonly Finding[], round: number): PatchedRounds =>
  findings.reduce<PatchedRounds>((acc, finding) => ({ ...acc, [finding.fingerprint]: round }), patchedAt);
