const ID_KEY = 'id';

/** The repo's IR byte form: two-space indent. */
const JSON_INDENT = 2;

export type IrIssue = { readonly path: string; readonly message: string };

export type IrResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly file: string; readonly issues: readonly IrIssue[] };

/** The marker a failed JSON parse or file read returns - distinct from every parsed value. */
const INVALID: unique symbol = Symbol('invalid');

const tryJson = (text: string): unknown => {
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return INVALID;
  }
};

const tryRead = (file: string): string | typeof INVALID => {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return INVALID;
  }
};

const rootIssues = (message: string): readonly IrIssue[] => [{ path: ROOT_PATH, message }];

/** The shape every zod issue carries; an `unrecognized_keys` issue adds the keys it refused. */
interface ZodIssueLike {
  readonly code: string;
  readonly path: readonly PropertyKey[];
  readonly message: string;
  /** Present only on `unrecognized_keys` issues: the keys the object refused. */
  readonly keys?: readonly string[];
}

/**
 * An `unrecognized_keys` issue is spelled at the key itself — that is where the unknown field
 * lives, and the path a reader can point at — not only in the message.
 */
const pathsOf = (raw: unknown, issue: ZodIssueLike): readonly string[] => {
  const base = issuePath(raw, issue.path);
  return issue.code === 'unrecognized_keys' && issue.keys !== undefined
    ? issue.keys.map(key => `${base}.${key}`)
    : [base];
};

/** The IrIssue form of a zod rejection: one line per refused key, each naming its own path. */
export const irIssues = (raw: unknown, issues: readonly ZodIssueLike[]): readonly IrIssue[] =>
  issues.flatMap(issue => pathsOf(raw, issue).map(path => ({ path, message: issue.message })));

